  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';
  document.getElementById('container').appendChild(canvas);

  var currentN = 6;
  var showComparison = false;

  var trueData = sampleSmooth(trueFunc, 400);
  var fitData = sampleFunction(networkFit, currentN, 400);
  var fit6Data = sampleFunction(networkFit, 6, 400);
  var fit50Data = sampleFunction(networkFit, 50, 400);

  var chart = new Chart(canvas, {
    type: 'scatter',
    data: {
      datasets: [
        {
          label: 'True function',
          data: trueData,
          showLine: true,
          borderColor: COL_BLACK,
          borderWidth: 2.5,
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          order: 3
        },
        {
          label: 'Network fit',
          data: fitData,
          showLine: true,
          borderColor: COL_TEAL,
          borderWidth: 2.5,
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          order: 2
        },
        {
          label: 'Training data',
          data: dataPoints,
          showLine: false,
          backgroundColor: COL_ORANGE,
          borderColor: COL_ORANGE,
          pointRadius: 5,
          pointHoverRadius: 7,
          order: 1
        },
        {
          label: '6-unit fit',
          data: [],
          showLine: true,
          borderColor: COL_TEAL,
          borderWidth: 2,
          borderDash: [6, 4],
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          hidden: true,
          order: 4
        },
        {
          label: '50-unit fit',
          data: [],
          showLine: true,
          borderColor: COL_TEAL_DARK,
          borderWidth: 2,
          borderDash: [6, 4],
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          hidden: true,
          order: 4
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 150 },
      plugins: {
        legend: { display: false },
        title: {
          display: true,
          text: '6 hidden units',
          font: { size: 14, family: 'sans-serif' },
          color: '#333'
        },
        tooltip: {
          callbacks: {
            label: function(ctx) {
              if (ctx.datasetIndex === 2) {
                return 'Data: (' + ctx.parsed.x.toFixed(2) + ', ' + ctx.parsed.y.toFixed(2) + ')';
              }
              return ctx.dataset.label + ': (' + ctx.parsed.x.toFixed(2) + ', ' + ctx.parsed.y.toFixed(2) + ')';
            }
          }
        }
      },
      scales: {
        x: {
          type: 'linear',
          min: 0,
          max: 1,
          title: { display: true, text: 'Input, x', font: { size: 13 } },
          ticks: { stepSize: 0.5, callback: function(v) { return v.toFixed(1); } },
          grid: { color: 'rgba(0,0,0,0.06)' }
