(function() {
  // True data-generating function
  function trueFunc(x) {
    return 0.65 * Math.sin(2 * Math.PI * (x - 0.07));
  }

  // Simulated network fit with N hidden units
  function networkFit(x, N) {
    var trueVal = trueFunc(x);
    // Amplitude of jagged perturbation decreases with N
    var amp = 1.5 * Math.pow(6.0 / N, 1.2);
    // Number of linear segments
    var numSegs = N + 1;
    var segWidth = 1.0 / numSegs;
    var segIdx = Math.min(Math.floor(x / segWidth), numSegs - 1);
    var localT = (x - segIdx * segWidth) / segWidth;

    // Continuous perturbation pattern
    function perturb(px) {
      return amp * Math.sin(3 * Math.PI * (px - 0.05)) * Math.sin(Math.PI * px);
    }

    // Piecewise-linear interpolation of perturbation
    var x0 = segIdx * segWidth;
    var x1 = (segIdx + 1) * segWidth;
    var p0 = perturb(x0);
    var p1 = perturb(x1);
    var perturbation = p0 + localT * (p1 - p0);

    // Small systematic offset decreasing with N
    var offset = 0.06 * (6.0 / N);
    return trueVal + perturbation + offset;
  }

  // Training data points (8 points with slight noise)
  var dataPoints = [
    {x: 0.05, y: -0.10},
    {x: 0.12, y: 0.22},
    {x: 0.20, y: 0.45},
    {x: 0.75, y: -0.70},
    {x: 0.82, y: -0.62},
    {x: 0.88, y: -0.55},
    {x: 0.93, y: -0.48},
    {x: 0.97, y: -0.42}
  ];

  // Generate sample points for a function, including segment boundaries for piecewise-linear
  function sampleFunction(fn, N, numBase) {
    var pts = [];
    var numSegs = N + 1;
    var segWidth = 1.0 / numSegs;
    var ptsPerSeg = Math.max(2, Math.ceil((numBase || 300) / numSegs));

    for (var s = 0; s < numSegs; s++) {
      var x0 = s * segWidth;
      var x1 = (s + 1) * segWidth;
      for (var i = 0; i <= ptsPerSeg; i++) {
        var x = x0 + (x1 - x0) * (i / ptsPerSeg);
        if (s > 0 && i === 0) continue; // avoid duplicate at boundary
        pts.push({x: x, y: fn(x, N)});
      }
    }
    return pts;
  }

  function sampleSmooth(fn, n) {
    var pts = [];
    for (var i = 0; i <= n; i++) {
      var x = i / n;
      pts.push({x: x, y: fn(x)});
    }
    return pts;
  }

  // Colors
  var COL_BLACK = '#1a1a1a';
  var COL_TEAL = '#7FDBDA';
