          ticks: { stepSize: 1, callback: function(v) { return v.toFixed(1); } },
          grid: { color: 'rgba(0,0,0,0.06)' }
        }
      }
    }
  });

  window.__markRendered();

  function updateChart() {
    fitData = sampleFunction(networkFit, currentN, 400);
    chart.data.datasets[1].data = fitData;
    chart.options.plugins.title.text = currentN + ' hidden units';

    if (showComparison) {
      chart.data.datasets[1].hidden = true;
      chart.data.datasets[3].data = fit6Data;
      chart.data.datasets[3].hidden = false;
      chart.data.datasets[4].data = fit50Data;
      chart.data.datasets[4].hidden = false;
    } else {
      chart.data.datasets[1].hidden = false;
      chart.data.datasets[3].hidden = true;
      chart.data.datasets[4].hidden = true;
    }
    chart.update();
  }

  // Interaction handlers
  window.update_hiddenUnits = function(v) {
    currentN = v;
    updateChart();
  };

  window.toggle_extremeComparison = function(on) {
    showComparison = on;
    updateChart();
  };

  // Demo steps
  var steps = [
    {
      title: 'Low capacity: 6 hidden units',
      narration: 'With only 6 hidden units, the network\'s output is a jagged piecewise-linear function with sharp kinks and large overshoots — it cannot represent the smooth curvature of the true sinusoidal function.',
      state: { hiddenUnits: 6, extremeComparison: false }
    },
    {
      title: 'Sweep capacity upward',
      narration: 'Drag the slider from 6 toward 50 and watch the teal fit curve progressively smooth out: kinks soften, overshoots shrink, and the approximation converges toward the black true function.',
      state: { hiddenUnits: 10, extremeComparison: false }
    },
    {
      title: 'High capacity: 50 hidden units',
      narration: 'At 50 hidden units the fit is smooth and nearly overlaps the true function — the network has enough capacity to represent the underlying sinusoid faithfully.',
      state: { hiddenUnits: 50, extremeComparison: false }
    },
    {
      title: 'A/B toggle comparison',
      narration: 'Toggle between the two extremes to see the qualitative jump: the 6-unit fit has visible angular artifacts while the 50-unit fit is indistinguishable from the true curve at a glance.',
      state: { hiddenUnits: 50, extremeComparison: true }
    }
  ];

  var currentStep = 0;

  function applyStep(idx) {
    currentStep = idx;
    var st = steps[idx];
    document.getElementById('demoNarration').textContent = st.narration;
    document.getElementById('stepLabel').textContent = (idx + 1) + '/' + steps.length;

    // Set slider
    var slider = document.getElementById('hiddenUnitsInput');
    slider.value = st.state.hiddenUnits;
    document.getElementById('hiddenUnitsVal').value = st.state.hiddenUnits;
    currentN = st.state.hiddenUnits;

    // Set toggle
    var toggle = document.getElementById('extremeComparisonInput');
    toggle.checked = st.state.extremeComparison;
    showComparison = st.state.extremeComparison;

    updateChart();
  }

  window.nextStep = function() {
    if (currentStep < steps.length - 1) applyStep(currentStep + 1);
  };

  window.prevStep = function() {
    if (currentStep > 0) applyStep(currentStep - 1);
  };

  // Initialize at step 0
  applyStep(0);
})();
