(function() {
  // True data-generating function
  function trueFunc(x) {
    return 0.65 * Math.sin(2 * Math.PI * (x - 0.07));
  }

  // Perturbation shape: Gaussian bumps that create the characteristic
  // overshoot/undershoot/kink pattern seen in low-capacity networks
  function perturbShape(x) {
    var p = 0;
    p += 1.5 * Math.exp(-Math.pow((x - 0.30) / 0.12, 2));
    p -= 1.8 * Math.exp(-Math.pow((x - 0.55) / 0.12, 2));
    p += 0.35 * Math.exp(-Math.pow((x - 0.85) / 0.06, 2));
    return p;
  }

  // Network fit with N hidden units: piecewise-linear perturbation
  // Amplitude decays as (6/N)^2 so N=50 is visually indistinguishable from truth
  function networkFit(x, N) {
    var trueVal = trueFunc(x);
    var amp = Math.pow(6.0 / N, 2.0);
    var numSegs = N + 1;
    var segWidth = 1.0 / numSegs;
    var segIdx = Math.min(Math.floor(x / segWidth), numSegs - 1);
    var localT = (x - segIdx * segWidth) / segWidth;

    var x0 = segIdx * segWidth;
    var x1 = (segIdx + 1) * segWidth;
    var p0 = amp * perturbShape(x0);
    var p1 = amp * perturbShape(x1);
    var perturbation = p0 + localT * (p1 - p0);

    return trueVal + perturbation;
  }

  // Training data points (8 points with slight noise)
  var dataPoints = [
    {x: 0.05, y: -0.10},
    {x: 0.12, y: 0.22},
    {x: 0.20, y: 0.45},
    {x: 0.75, y: -0.70},
    {x: 0.82, y: -0.62},
    {x: 0.88, y: -0.55},
    {x: 0.93, y: -0.48},
    {x: 0.97, y: -0.42}
  ];

  // Sample with segment-boundary awareness for piecewise-linear rendering
  function sampleFunction(fn, N, numBase) {
    var pts = [];
    var numSegs = N + 1;
    var segWidth = 1.0 / numSegs;
    var ptsPerSeg = Math.max(2, Math.ceil((numBase || 300) / numSegs));

    for (var s = 0; s < numSegs; s++) {
      var x0 = s * segWidth;
      var x1 = (s + 1) * segWidth;
      for (var i = 0; i <= ptsPerSeg; i++) {
        var x = x0 + (x1 - x0) * (i / ptsPerSeg);
        if (s > 0 && i === 0) continue;
        pts.push({x: x, y: fn(x, N)});
      }
    }
    return pts;
  }

  function sampleSmooth(fn, n) {
    var pts = [];
    for (var i = 0; i <= n; i++) {
      var x = i / n;
      pts.push({x: x, y: fn(x)});
    }
    return pts;
