      state: { hiddenUnits: 50, extremeComparison: true, showTrueOnly: false }
    }
  ];

  var currentStep = 0;

  function applyStep(idx) {
    currentStep = idx;
    var st = steps[idx];
    document.getElementById('demoNarration').textContent = st.narration;
    document.getElementById('stepLabel').textContent = (idx + 1) + '/' + steps.length;

    // Set slider
    var slider = document.getElementById('hiddenUnitsInput');
    slider.value = st.state.hiddenUnits;
    document.getElementById('hiddenUnitsVal').value = st.state.hiddenUnits;
    currentN = st.state.hiddenUnits;

    // Set comparison toggle
