    // Set true-only toggle
    var trueOnlyToggle = document.getElementById('showTrueOnlyInput');
    trueOnlyToggle.checked = st.state.showTrueOnly;
    showTrueOnly = st.state.showTrueOnly;

    updateChart();
  }

  window.nextStep = function() {
    if (currentStep < steps.length - 1) applyStep(currentStep + 1);
  };

  window.prevStep = function() {
    if (currentStep > 0) applyStep(currentStep - 1);
  };

  // Initialize at step 0 (true function only, reproducing panel a)
  applyStep(0);
})();
