// @FIGURE_CODE_BEGIN
(function() {
  // True data-generating function: sinusoid matching source
  // Starts near -0.3, peaks ~0.6 at x≈0.25, troughs ~-0.6 at x≈0.75
  function trueFunc(x) {
    return 0.65 * Math.sin(2 * Math.PI * (x - 0.07));
  }

  // Perturbation shape: creates characteristic overshoot/undershoot pattern
  // Wider Gaussians ensure perturbation reaches both peak and trough regions
  function perturbShape(x) {
    var p = 0;
    p += 1.3 * Math.exp(-Math.pow((x - 0.30) / 0.12, 2));
    p -= 1.8 * Math.exp(-Math.pow((x - 0.60) / 0.18, 2));
    p += 0.35 * Math.exp(-Math.pow((x - 0.85) / 0.06, 2));
    return p;
  }

  // Network fit with N hidden units: piecewise-linear perturbation
  // Amplitude decays as (6/N)^5 for rapid convergence matching source panels
  function networkFit(x, N) {
    var trueVal = trueFunc(x);
    var amp = 1.5 * Math.pow(6.0 / N, 5.0);
    var numSegs = N + 1;
    var segWidth = 1.0 / numSegs;
    var segIdx = Math.min(Math.floor(x / segWidth), numSegs - 1);
    var localT = (x - segIdx * segWidth) / segWidth;

    var x0 = segIdx * segWidth;
    var x1 = (segIdx + 1) * segWidth;
    var p0 = amp * perturbShape(x0);
    var p1 = amp * perturbShape(x1);
    var perturbation = p0 + localT * (p1 - p0);

    return trueVal + perturbation;
  }

  // Training data points (8 points with slight noise, matching source)
  var dataPoints = [
    {x: 0.05, y: -0.10},
    {x: 0.12, y: 0.22},
    {x: 0.20, y: 0.48},
    {x: 0.75, y: -0.70},
    {x: 0.82, y: -0.65},
    {x: 0.88, y: -0.55},
    {x: 0.93, y: -0.48},
    {x: 0.97, y: -0.42}
  ];

  // Sample with segment-boundary awareness for piecewise-linear rendering
  function sampleFunction(fn, N, numBase) {
    var pts = [];
    var numSegs = N + 1;
    var segWidth = 1.0 / numSegs;
    var ptsPerSeg = Math.max(2, Math.ceil((numBase || 300) / numSegs));

    for (var s = 0; s < numSegs; s++) {
      var x0 = s * segWidth;
      var x1 = (s + 1) * segWidth;
      for (var i = 0; i <= ptsPerSeg; i++) {
        var x = x0 + (x1 - x0) * (i / ptsPerSeg);
        if (s > 0 && i === 0) continue;
        pts.push({x: x, y: fn(x, N)});
      }
    }
    return pts;
  }

  function sampleSmooth(fn, n) {
    var pts = [];
    for (var i = 0; i <= n; i++) {
      var x = i / n;
      pts.push({x: x, y: fn(x)});
    }
    return pts;
  }

  // Colors matching source exactly
  var COL_BLACK = '#1a1a1a';
  var COL_TEAL = '#7FDBDA';
  var COL_ORANGE = '#E8956D';
  var COL_TEAL_DARK = '#4ABFBF';

  // Build chart
  var canvas = document.createElement('canvas');
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';
  document.getElementById('container').appendChild(canvas);

  var currentN = 6;
  var showComparison = false;
  var showTrueOnly = false;

  var trueData = sampleSmooth(trueFunc, 400);
  var fitData = sampleFunction(networkFit, currentN, 400);
  var fit6Data = sampleFunction(networkFit, 6, 400);
  var fit50Data = sampleFunction(networkFit, 50, 400);

  var chart = new Chart(canvas, {
    type: 'scatter',
    data: {
      datasets: [
        {
          label: 'True function',
          data: trueData,
          showLine: true,
          borderColor: COL_BLACK,
          borderWidth: 2.5,
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          order: 3
        },
        {
          label: 'Network fit',
          data: fitData,
          showLine: true,
          borderColor: COL_TEAL,
          borderWidth: 2.5,
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          order: 2
        },
        {
          label: 'Training data',
          data: dataPoints,
          showLine: false,
          backgroundColor: COL_ORANGE,
          borderColor: COL_ORANGE,
          pointRadius: 5,
          pointHoverRadius: 7,
          order: 1
        },
        {
          label: '6-unit fit',
          data: [],
          showLine: true,
          borderColor: COL_TEAL,
          borderWidth: 2,
          borderDash: [6, 4],
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          hidden: true,
          order: 4
        },
        {
          label: '50-unit fit',
          data: [],
          showLine: true,
          borderColor: COL_TEAL_DARK,
          borderWidth: 2,
          borderDash: [6, 4],
          pointRadius: 0,
          pointHitRadius: 0,
          tension: 0,
          hidden: true,
          order: 4
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 150 },
      plugins: {
        legend: { display: false },
        title: {
          display: true,
          text: 'b) 6 hidden units',
          font: { size: 14, family: 'sans-serif' },
          color: '#333'
        },
        tooltip: {
          callbacks: {
            label: function(ctx) {
              if (ctx.datasetIndex === 2) {
                return 'Data: (' + ctx.parsed.x.toFixed(2) + ', ' + ctx.parsed.y.toFixed(2) + ')';
              }
              return ctx.dataset.label + ': (' + ctx.parsed.x.toFixed(2) + ', ' + ctx.parsed.y.toFixed(2) + ')';
            }
          }
        }
      },
      scales: {
        x: {
          type: 'linear',
          min: 0,
          max: 1,
          title: { display: true, text: 'Input, x', font: { size: 13 } },
          ticks: { stepSize: 0.5, callback: function(v) { return v.toFixed(1); } },
          grid: { display: false },
          border: { color: '#333', width: 1.5 }
        },
        y: {
          type: 'linear',
          min: -1,
          max: 1,
          title: { display: true, text: 'Output, y', font: { size: 13 } },
          ticks: { stepSize: 1, callback: function(v) { return v.toFixed(1); } },
          grid: { display: false },
          border: { color: '#333', width: 1.5 }
        }
      }
    }
  });

  window.__markRendered();

  // Panel definitions matching source figure
  var panelDefs = [
    { letter: 'a', title: 'a) True function only', N: null, trueOnly: true, comparison: false },
    { letter: 'b', title: 'b) 6 hidden units', N: 6, trueOnly: false, comparison: false },
    { letter: 'c', title: 'c) 7 hidden units', N: 7, trueOnly: false, comparison: false },
    { letter: 'd', title: 'd) 8 hidden units', N: 8, trueOnly: false, comparison: false },
    { letter: 'e', title: 'e) 10 hidden units', N: 10, trueOnly: false, comparison: false },
    { letter: 'f', title: 'f) 50 hidden units', N: 50, trueOnly: false, comparison: false }
  ];

  function highlightPanelBtn(idx) {
    for (var i = 0; i < 6; i++) {
      var btn = document.getElementById('panelBtn' + i);
      if (btn) btn.style.background = (i === idx) ? '#c8e6ff' : '#f5f5f5';
    }
  }

  function updateChart() {
    fitData = sampleFunction(networkFit, currentN, 400);
    chart.data.datasets[1].data = fitData;

    if (showTrueOnly) {
      chart.options.plugins.title.text = 'a) True function only';
      chart.data.datasets[1].hidden = true;
      chart.data.datasets[3].hidden = true;
      chart.data.datasets[4].hidden = true;
      highlightPanelBtn(0);
    } else if (showComparison) {
      chart.options.plugins.title.text = 'Comparison: 6 vs 50 hidden units';
      chart.data.datasets[1].hidden = true;
      chart.data.datasets[3].data = fit6Data;
      chart.data.datasets[3].hidden = false;
      chart.data.datasets[4].data = fit50Data;
      chart.data.datasets[4].hidden = false;
      highlightPanelBtn(-1);
    } else {
      // Find matching panel
      var panelIdx = -1;
      for (var i = 1; i < panelDefs.length; i++) {
        if (panelDefs[i].N === currentN) { panelIdx = i; break; }
      }
      if (panelIdx >= 0) {
        chart.options.plugins.title.text = panelDefs[panelIdx].title;
        highlightPanelBtn(panelIdx);
      } else {
        chart.options.plugins.title.text = currentN + ' hidden units';
        highlightPanelBtn(-1);
      }
      chart.data.datasets[1].hidden = false;
      chart.data.datasets[3].hidden = true;
      chart.data.datasets[4].hidden = true;
    }
    chart.update();
  }

  // Panel selector
  window.selectPanel = function(idx) {
    var p = panelDefs[idx];
    showTrueOnly = p.trueOnly;
    showComparison = p.comparison;
    if (p.N !== null) currentN = p.N;

    document.getElementById('showTrueOnlyInput').checked = showTrueOnly;
    document.getElementById('extremeComparisonInput').checked = showComparison;
    if (p.N !== null) {
      document.getElementById('hiddenUnitsInput').value = p.N;
      document.getElementById('hiddenUnitsVal').value = p.N;
    }
    updateChart();
  };

  // Interaction handlers
  window.update_hiddenUnits = function(v) {
    currentN = v;
    showTrueOnly = false;
    document.getElementById('showTrueOnlyInput').checked = false;
    updateChart();
  };

  window.toggle_extremeComparison = function(on) {
    showComparison = on;
    if (on) {
      showTrueOnly = false;
      document.getElementById('showTrueOnlyInput').checked = false;
    }
    updateChart();
  };

  window.toggle_showTrueOnly = function(on) {
    showTrueOnly = on;
    if (on) {
      showComparison = false;
      document.getElementById('extremeComparisonInput').checked = false;
    }
    updateChart();
  };

  // Demo steps (5 steps matching source panels + guided exploration)
  var steps = [
    {
      title: 'Low capacity: 6 hidden units',
      narration: 'With only 6 hidden units, the network\u2019s output is a jagged piecewise-linear function with sharp kinks and large overshoots \u2014 it cannot represent the smooth curvature of the true sinusoidal function.',
      state: { hiddenUnits: 6, extremeComparison: false, showTrueOnly: false }
    },
    {
      title: 'Sweep capacity upward',
      narration: 'Drag the slider from 6 toward 50 and watch the teal fit curve progressively smooth out: kinks soften, overshoots shrink, and the approximation converges toward the black true function.',
      state: { hiddenUnits: 10, extremeComparison: false, showTrueOnly: false }
    },
    {
      title: 'High capacity: 50 hidden units',
      narration: 'At 50 hidden units the fit is smooth and nearly overlaps the true function \u2014 the network has enough capacity to represent the underlying sinusoid faithfully.',
      state: { hiddenUnits: 50, extremeComparison: false, showTrueOnly: false }
    },
    {
      title: 'A/B toggle comparison',
      narration: 'Toggle between the two extremes to see the qualitative jump: the 6-unit fit has visible angular artifacts while the 50-unit fit is indistinguishable from the true curve at a glance.',
      state: { hiddenUnits: 50, extremeComparison: true, showTrueOnly: false }
    },
    {
      title: 'True function only (panel a)',
      narration: 'This is the true data-generating function: a smooth sinusoid. The orange dots are noisy training samples. Use the panel buttons (a\u2013f) above to jump directly to any panel from the source figure.',
      state: { hiddenUnits: 6, extremeComparison: false, showTrueOnly: true }
    }
  ];

  var currentStep = 0;

  function applyStep(idx) {
    currentStep = idx;
    var st = steps[idx];
    document.getElementById('demoNarration').textContent = st.narration;
    document.getElementById('stepLabel').textContent = (idx + 1) + '/' + steps.length;

    var slider = document.getElementById('hiddenUnitsInput');
    slider.value = st.state.hiddenUnits;
    document.getElementById('hiddenUnitsVal').value = st.state.hiddenUnits;
    currentN = st.state.hiddenUnits;

    var toggle = document.getElementById('extremeComparisonInput');
    toggle.checked = st.state.extremeComparison;
    showComparison = st.state.extremeComparison;

    var trueOnlyToggle = document.getElementById('showTrueOnlyInput');
    trueOnlyToggle.checked = st.state.showTrueOnly;
    showTrueOnly = st.state.showTrueOnly;

    updateChart();
  }

  window.nextStep = function() {
    if (currentStep < steps.length - 1) applyStep(currentStep + 1);
  };

  window.prevStep = function() {
    if (currentStep > 0) applyStep(currentStep - 1);
  };

  // Initialize at step 0 (6 hidden units, matching panel b)
  applyStep(0);
})();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
